//! The language/script detection port against laya's own answers: outputs of
//! laya 0.3.28's `lang.py` (`tests/fixtures/lang.json`, regenerated by
//! `tests/fixtures/lang.py`), with the cases laya 0.4.35 answers differently
//! edited by hand (listed in `lang.py`), and laya 0.4.35's recorded probe
//! (`tests/fixtures/upstream/lang_probe.json`).
use judge_laya::lang::{analyse, typed_decisions_workflow};
use serde_json::{Value, json};
use std::collections::BTreeMap;

/// Every field of `analyse(input)` that differs from `expected`, or that
/// `expected` lacks (indexing would read a missing field as null).
fn mismatches(name: &str, input: &Value, expected: &Value) -> Vec<String> {
    let got = analyse(input);
    let got = json!({
        "script": got.script,
        "language": got.language,
        "is_english": got.is_english,
        "language_undecided": got.language_undecided,
        // Rounded like Python's round(x, 4), so equal to the last bit.
        "diacritic_rate": got.diacritic_rate,
        "non_latin_fraction": got.non_latin_fraction,
        "mixed_segment": got.mixed_segment,
    });
    got.as_object()
        .unwrap()
        .iter()
        .filter(|(field, value)| expected.get(field.as_str()) != Some(*value))
        .map(|(field, value)| {
            let expected = expected
                .get(field)
                .map_or("nothing".into(), Value::to_string);
            format!("{name}: {field} {value}, expected {expected}")
        })
        .collect()
}

/// A recorded case's `key`, which must be there (an explicit null is a value).
fn field<'a>(case: &'a Value, key: &str) -> &'a Value {
    case.get(key)
        .unwrap_or_else(|| panic!("case without {key}: {case}"))
}

#[test]
fn detection_matches_laya_python_fixtures() {
    let fixtures: BTreeMap<String, Value> =
        serde_json::from_str(include_str!("fixtures/lang.json")).unwrap();
    assert!(fixtures.len() >= 100);
    let failures: Vec<String> = fixtures
        .iter()
        .flat_map(|(name, case)| mismatches(name, field(case, "input"), field(case, "expected")))
        .collect();
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn detection_matches_laya_recorded_probe() {
    let probe: Vec<Value> =
        serde_json::from_str(include_str!("fixtures/upstream/lang_probe.json")).unwrap();
    assert_eq!(probe.len(), 261);
    let failures: Vec<String> = probe
        .iter()
        .flat_map(|case| {
            mismatches(
                case["label"].as_str().unwrap(),
                field(case, "state"),
                field(case, "analyse"),
            )
        })
        .collect();
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Letters assigned after Unicode 14 (laya's `_is_letter` table) are letters
/// here too: a Garay word is neither unknown nor English.
#[test]
fn recent_letters_are_letters() {
    let detection = analyse(&json!("\u{10D4A}\u{10D4B}\u{10D4C}\u{10D4D}"));
    assert_ne!(detection.script, "unknown");
    assert!(!detection.is_english);
}

/// laya 0.4.35 cases the fixtures and the probe do not reach.
#[test]
fn shouting_and_mixed_fields_keep_their_language() {
    // An English field does not outvote a German one: the German field's
    // language, though no German line passes the line scan, is the verdict.
    let mixed = analyse(&json!({
        "a": "Please check the order status for this customer and reply with the tracking number that was sent.",
        "b": "Die Rückerstattung die Bestellung die Lieferung",
    }));
    assert_eq!((mixed.language, mixed.is_english), (Some("de"), false));
    // Non-English letters are evidence enough for an all-caps line whose stop
    // words are all acronym-short.
    let shouted = analyse(&json!("DIE LIEFERUNG KAM ZU SPÄT"));
    assert_eq!((shouted.language, shouted.is_english), (Some("de"), false));
    // A five-letter all-caps run is emphasis on a word, not an acronym to blank.
    let emphasis = analyse(&json!("Das Paket kam NICHT an"));
    assert_eq!(
        (emphasis.language, emphasis.is_english),
        (Some("de"), false)
    );
}

#[test]
fn workflow_signatures_need_the_exact_question_ids() {
    let full = ["urgency", "action", "category", "churn_risk", "needs_human"];
    assert_eq!(
        typed_decisions_workflow(full.into_iter()),
        Some("customer_service")
    );
    assert_eq!(typed_decisions_workflow(full[..4].iter().copied()), None);
    let extra = [
        "urgency",
        "action",
        "category",
        "churn_risk",
        "needs_human",
        "extra",
    ];
    assert_eq!(typed_decisions_workflow(extra.into_iter()), None);
}
